'use strict';
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const paths={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',inbox:'M3 4h18v16H3zM3 13h5l2 3h4l2-3h5',academy:'M5 21V3h14v18M9 7h1m4 0h1M9 11h1m4 0h1M10 21v-5h4v5',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',check:'M5 12l4 4L19 6',close:'m6 6 12 12M6 18 18 6',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',clock:'M12 7v5l4 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',switch:'M4 7h16l-4-4M20 17H4l4 4',file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h8',person:'M17 7a5 5 0 1 1-10 0 5 5 0 0 1 10 0M3 22v-3a9 9 0 0 1 18 0v3',settings:'M5 7h14M5 17h14M9 4v6M15 14v6'};
function icon(name){return `<svg class="icon ${name==='arrow'?'directional':''}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
function btn(label,action,kind='',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`}
function badge(label,kind=''){return `<span class="status ${kind}">${esc(label)}</span>`}
function notice(title,body,kind='info'){return `<div class="notice ${kind}" role="status"><b>${esc(title)}</b>${body}</div>`}
function property(key,value){return `<div class="property"><span>${esc(key)}</span><span>${value}</span></div>`}
function field(key,label,value='',type='text',hint='',dir=''){return `<label class="field" for="${key}">${esc(label)}<input id="${key}" name="${key}" type="${type}" value="${esc(value)}" ${dir?`dir="${dir}"`:''} maxlength="160" required>${hint?`<small>${esc(hint)}</small>`:''}</label>`}
function head(title,subtitle,actions='',id=''){return `<div class="eyebrow">${esc(id)}</div><div class="pagehead"><div><h1 tabindex="-1">${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div>${actions?`<div class="page-tools">${actions}</div>`:''}</div>`}
function errorBox(){return M.error?`<div class="notice error" role="alert" tabindex="-1" id="form-error">${esc(M.error)}</div>`:''}
function footer(action,label,back='setup'){return `<div class="form-footer"><span class="muted">${esc(t('notLive'))}</span><div class="actions">${btn(t('back'),'nav:'+back)}${btn(t(label),action,'primary')}</div></div>`}
function steps(active){return `<div class="steps">${['branch','sport','review'].map((x,i)=>`<span class="step ${x===active?'active':''}"><span class="step-circle">${i+1}</span>${esc(t(x))}</span>`).join('')}</div>`}
function ask(title,body,yes){const d=document.getElementById('confirm-dialog');d.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2><p>${esc(body)}</p><div class="actions"><button class="btn" id="dialog-cancel">${esc(t('cancel'))}</button><button class="btn primary" id="dialog-yes">${esc(t('confirm'))}</button></div>`;const previous=document.activeElement;d.showModal();d.querySelector('#dialog-cancel').onclick=()=>{d.close();previous?.focus()};d.querySelector('#dialog-yes').onclick=()=>{d.close();yes()}}
